//go:build ignore

// Command gen records what an SDK v0.21.0 plugin sends on the log lane: its
// compiled logs.proto descriptor, the create reply for a request that carries the
// replay-markers parameter (which v0.21.0 does not know and echoes), and the
// output frames of a session that replays two lines and ends.
//
// The files are the frozen "old plugin" the compatibility tests decode with the
// current code, and the frozen "old reader" schema they encode against. To
// regenerate, run it from a checkout of the v0.21.0 tag, never from a newer tree
// (event timestamps are the wall clock, so regenerated bytes differ; the tests do
// not depend on them):
//
//	git worktree add --detach /tmp/sdk-v0.21.0 v0.21.0
//	cd /tmp/sdk-v0.21.0
//	GOWORK=off GOTOOLCHAIN=local go run /path/to/gen.go /path/to/testdata/compat-v0.21.0
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"google.golang.org/protobuf/encoding/protodelim"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protodesc"

	logging "github.com/omniviewdev/plugin-sdk/log"
	"github.com/omniviewdev/plugin-sdk/pkg/types"
	"github.com/omniviewdev/plugin-sdk/pkg/utils/timeutil"
	logs "github.com/omniviewdev/plugin-sdk/pkg/v1/logs"
	"github.com/omniviewdev/plugin-sdk/pkg/v1/logs/logtest"
	logspb "github.com/omniviewdev/plugin-sdk/proto/v1/logs"
)

const sessionID = "11111111-1111-4111-8111-111111111111"

func main() {
	if len(os.Args) != 2 {
		fail(fmt.Errorf("usage: gen <output directory>"))
	}
	dir := os.Args[1]

	descriptor, err := proto.MarshalOptions{Deterministic: true}.Marshal(
		protodesc.ToFileDescriptorProto(logspb.File_proto_v1_logs_logs_proto))
	fail(err)
	fail(os.WriteFile(filepath.Join(dir, "logs.fdp"), descriptor, 0o600))

	out := logtest.NewRecordingOutput()
	manager := logs.NewManager(logs.ManagerConfig{
		Logger: logging.NewNop(),
		Handlers: map[string]logs.Handler{"test/pod": {
			Plugin: "test", Resource: "pod",
			Handler: func(*types.PluginContext, logs.LogStreamRequest) (io.ReadCloser, error) {
				return io.NopCloser(strings.NewReader(
					"2026-01-02T03:04:05.000000001Z first\n2026-01-02T03:04:06.000000002Z second\n")), nil
			},
		}},
		Sink:  out,
		Clock: timeutil.NewInstantFakeClock(),
	})
	defer manager.Close()
	session, err := manager.CreateResourceSession(
		types.NewPluginContext(context.Background(), "test", nil, nil, nil),
		logs.CreateSessionOptions{
			SessionID: sessionID, ResourceKey: "pod", ResourceID: "default/web-1",
			Options: logs.LogSessionOptions{
				Follow: true, IncludeTimestamps: true, IncludeSourceEvents: true, TailLines: 100,
				// A reader that asks for replay markers; v0.21.0 does not know the key.
				Params: map[string]string{"omniview.log.replay-markers": "1"},
			},
		})
	fail(err)
	if out.WaitForEvent(logs.StreamEventStreamEnded, 5*time.Second) == nil {
		fail(fmt.Errorf("the session did not end"))
	}

	reply, err := proto.MarshalOptions{Deterministic: true}.Marshal(
		&logspb.ResourceLogSessionResponse{ResourceWireVersion: logs.ResourceSessionWireVersion, Session: session.ToProto()})
	fail(err)
	fail(os.WriteFile(filepath.Join(dir, "create_reply.pb"), reply, 0o600))

	var frames bytes.Buffer
	for _, line := range out.Lines() {
		_, err = protodelim.MarshalTo(&frames, &logspb.LogStreamOutput{
			SessionId: line.SessionID, Payload: &logspb.LogStreamOutput_Line{Line: line.ToProto()}})
		fail(err)
	}
	for _, event := range out.Events() {
		_, err = protodelim.MarshalTo(&frames, &logspb.LogStreamOutput{
			SessionId: session.ID, Payload: &logspb.LogStreamOutput_Event{Event: event.ToProto()}})
		fail(err)
	}
	fail(os.WriteFile(filepath.Join(dir, "stream.pb"), frames.Bytes(), 0o600))
}

func fail(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, "gen:", err)
		os.Exit(1)
	}
}
